<?php require_once '../config/auth.php';requireLogin();require_once '../config/database.php';$id=(int)$_GET['id'];$r=$conn->query("SELECT * FROM utilizadores WHERE id=$id")->fetch_assoc();if($_SERVER['REQUEST_METHOD']==='POST'){$nome=trim($_POST['nome']);$email=trim($_POST['email']);$tipo=$_POST['tipo'];$s=$conn->prepare("UPDATE utilizadores SET nome=?,email=?,tipo=? WHERE id=?");$s->bind_param('sssi',$nome,$email,$tipo,$id);$s->execute();if(!empty($_POST['senha'])){$h=password_hash($_POST['senha'],PASSWORD_DEFAULT);$s=$conn->prepare("UPDATE utilizadores SET senha=? WHERE id=?");$s->bind_param('si',$h,$id);$s->execute();}header('Location: index.php');exit;}?><!doctype html><html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar utilizador</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="container"><div class="card"><h1>Editar utilizador</h1><form method="post"><input name="nome" value="<?=htmlspecialchars($r['nome'])?>" required><input type="email" name="email" value="<?=htmlspecialchars($r['email'])?>" required><input type="password" name="senha" placeholder="Nova senha (opcional)"><select name="tipo"><option value="leitor" <?=$r['tipo']=='leitor'?'selected':''?>>Leitor</option><option value="funcionario" <?=$r['tipo']=='funcionario'?'selected':''?>>Funcionário</option><option value="admin" <?=$r['tipo']=='admin'?'selected':''?>>Administrador</option></select><button>Actualizar</button></form></div></div></body></html>
